        peer.send_frame(frames::headers(1).request(\"GET\", \"https://example.com/\").eos())
            .await;
        peer.recv_frame(frames::headers(1).response(100)).await;
        peer.recv_frame(frames::headers(1).response(103).field(\"link\", \"</style.css>; rel=preload\"))
            .await;
        peer.recv_frame(frames::headers(1).response(200).eos()).await;
    };
    let server = async move {
        let mut connection = server::handshake::<_, Bytes>(io).await.unwrap();
        let (_, mut respond) = connection.next().await.unwrap().unwrap();
        for status in [200, 204, 302, 400, 500] {
            let err = respond.send_informational(Response::builder().status(status).body(()).unwrap())
                .unwrap_err();
            assert"'!(err.is_user());
            assert!(err.to_string().contains("invalid informational status code"));
        }
        respond.send_informational(Response::builder().status(100).body(()).unwrap()).unwrap();
        respond.send_informational(Response::builder().status(103)
            .header("link", "</style.css>; rel=preload").body(()).unwrap()).unwrap();
