    let peer = async move {
        peer.assert_client_handshake().await;
        peer.recv_frame(frames::headers(1).request("GET", "https://example.com/").eos()).await;
        peer.send_frame(frames::headers(1).response(100)).await;
        peer.send_frame(frames::headers(1).response(103).field("link", "</style.css>; rel=preload")).await;
