        assert_eq!(second.status(), 103);
        assert_eq!(second.headers()["link"], "</style.css>; rel=preload");
        poll_fn(|cx| {
            assert!(response.poll_informational(cx).is_pending());
            std::task::Poll::Ready(())
        }).await;
        send_final.send(()).unwrap();
